{%- set t = T[L] -%}
{%- set COLORS = {"Red":"#E03A3A","Green":"#2FA866","Yellow":"#F2B705","Blue":"#2F6FDE"} -%}
{%- macro v(x) -%}{{ (x or "") | e }}{%- endmacro -%}
{%- macro tm(x) -%}{{ (x | string)[:5] if x else "" }}{%- endmacro -%}
{%- macro dt(x) -%}{{ frappe.utils.formatdate(x, "dd-MM-yyyy") if x else "" }}{%- endmacro -%}
{%- macro txt(x) -%}{{ (x or "") | e | replace("\n", "<br>") }}{%- endmacro -%}
{%- macro cb(on) -%}<i class="cb{{ ' on' if on else '' }}"></i>{%- endmacro -%}
{%- macro sig(field, role, extra="") -%}
<div class="sig"{{ extra }}>{% if doc.get(field) %}<img class="sig-img" src="{{ doc.get(field) }}">{% endif %}<div class="cap"><b>{{ t.signature }}</b>·<span>{{ t[role] }}</span></div></div>
{%- endmacro -%}
<link href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&family=Rubik:wght@500;600;700&family=Noto+Nastaliq+Urdu:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
@page{size:A4;margin:0}
.print-format{padding:0!important;margin:0 auto!important;max-width:none!important;width:210mm!important;background:#fff}
.print-format .wp{--font-display:"Rubik","Noto Nastaliq Urdu","Segoe UI",sans-serif;--font-body:"Figtree","Noto Nastaliq Urdu","Segoe UI",sans-serif;
  --font-mono:"IBM Plex Mono","Noto Nastaliq Urdu",monospace;--ink:#101F33;--muted:#5A6B82;--rule:#9AA8BA;--soft:#EEF2F8;
  --navy:#16233A;--brand:#1F55C4;--brand-soft:#E3ECFB;--hazard:#FFC21A;--hazard-soft:#FFF4D0;--hazard-edge:#C99700;--on-hazard:#2B2100;
  -webkit-print-color-adjust:exact;print-color-adjust:exact}
.wp *{box-sizing:border-box}
.wp p,.wp h1,.wp h2,.wp h3{margin:0}
.wp .page{--fs:9pt;position:relative;width:210mm;min-height:296mm;background:#fff;color:var(--ink);font-family:var(--font-body);
  font-size:var(--fs);line-height:1.35;display:flex;flex-direction:column;gap:3mm;padding:7mm 8mm 5mm 14mm}
.wp[dir="rtl"] .page{padding:7mm 14mm 5mm 8mm}
.wp .page::before{content:"";position:absolute;top:0;bottom:0;left:0;width:6mm;background:repeating-linear-gradient(-45deg,var(--hazard) 0 4mm,var(--navy) 4mm 8mm)}
.wp .page::after{content:"";position:absolute;top:0;bottom:0;left:6mm;width:.7mm;background:var(--navy)}
.wp[dir="rtl"] .page::before{left:auto;right:0}
.wp[dir="rtl"] .page::after{left:auto;right:6mm}
.wp .head{display:grid;grid-template-columns:1fr auto;gap:6mm;align-items:stretch}
.wp .brand{display:flex;gap:4mm;align-items:center;min-width:0}
.wp .mark{flex:none;width:17mm;height:17mm;border-radius:2mm;background:#fff;display:flex;align-items:center;justify-content:center}
.wp .mark img{max-width:17mm;max-height:17mm;object-fit:contain}
.wp .kicker{font:600 .78em/1.3 var(--font-mono);letter-spacing:.04em;color:var(--muted)}
.wp .org{font:700 1.95em/1.15 var(--font-display);margin-top:.6mm;color:var(--navy)}
.wp .title{display:inline-block;margin-top:1.4mm;padding:.4mm 3mm;background:var(--navy);color:#fff;border-radius:1mm;font:600 .9em/1.5 var(--font-display);letter-spacing:.2em;text-transform:uppercase}
.wp .ticket{display:grid;grid-template-columns:auto auto;border:.4mm solid var(--navy);border-radius:2.5mm;overflow:hidden;min-width:66mm}
.wp .ticket .no{padding:1.8mm 4mm;background:var(--hazard-soft);border-right:.4mm dashed var(--navy);display:flex;flex-direction:column;justify-content:center}
.wp[dir="rtl"] .ticket .no{border-right:0;border-left:.4mm dashed var(--navy)}
.wp .ticket .no label{font:600 .72em/1.3 var(--font-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.wp .ticket .no .big{min-height:9mm;min-width:26mm;border-bottom:.35mm solid var(--navy);font:700 1.6em/9mm var(--font-mono);color:var(--navy)}
.wp .ticket .meta{padding:1.4mm 3mm;display:flex;flex-direction:column;gap:1mm;justify-content:center;min-width:36mm}
.wp .colour{display:inline-flex;align-items:center;gap:1.4mm;font-weight:600;margin-top:1mm;font-size:.85em}
.wp .colour i{width:3.6mm;height:3.6mm;border-radius:50%;display:inline-block}
.wp .sec{display:flex;flex-direction:column;min-width:0}
.wp .sec-h{display:flex;align-items:center;gap:2.4mm;padding:.9mm 2.4mm .9mm 1mm;background:var(--navy);color:#fff;border-radius:1.6mm}
.wp .sec-h .n{flex:none;width:5.4mm;height:5.4mm;border-radius:50%;background:var(--hazard);color:var(--on-hazard);display:flex;align-items:center;justify-content:center;font:700 .95em/1 var(--font-mono)}
.wp .sec-h h2{font:600 1.08em/1.4 var(--font-display);color:#fff}
.wp .sec-h .aside{margin-left:auto;font-size:.8em;color:#B9C7DB}
.wp[dir="rtl"] .sec-h .aside{margin-left:0;margin-right:auto}
.wp .sec-b{padding:2mm 0 0;display:flex;flex-direction:column;gap:2.2mm;flex:1}
.wp .f{display:flex;flex-direction:column;min-width:0}
.wp .f>label,.wp .lbl{font-size:.8em;font-weight:600;color:var(--muted);line-height:1.35;margin:0}
.wp .line{min-height:6.2mm;border-bottom:.3mm solid var(--ink);font-weight:600;padding-top:1mm;color:var(--ink)}
.wp .line small{font-weight:500;color:var(--muted)}
.wp .ruled{flex:1;min-height:11mm;border:.3mm solid var(--rule);border-radius:1.4mm;padding:.6mm 1.6mm;line-height:5.7mm;
  background:repeating-linear-gradient(to bottom,transparent 0 5.4mm,#C3CDDA 5.4mm 5.7mm)}
.wp .row2{display:grid;grid-template-columns:1fr 1fr;gap:3mm}
.wp .row3{display:grid;grid-template-columns:1fr 1fr 1.2fr;gap:3mm}
.wp .cb{display:inline-flex;align-items:center;justify-content:center;flex:none;width:3.8mm;height:3.8mm;border:.35mm solid var(--ink);border-radius:.8mm;background:#fff;vertical-align:middle;font-style:normal}
.wp .cb.on{background:var(--navy)}
.wp .cb.on::after{content:"\2713";color:#fff;font-size:3mm;font-weight:700;line-height:1}
.wp .cbl{display:inline-flex;align-items:center;gap:1.6mm;font-weight:600}
.wp .cols{flex:1;display:grid;grid-template-columns:1.13fr .87fr;gap:5mm}
.wp .col{display:flex;flex-direction:column;gap:3mm;min-width:0}
.wp .window{border:.3mm solid var(--rule);border-radius:2mm;padding:1.8mm 2.4mm 2mm;background:var(--soft);display:flex;flex-direction:column;gap:1.6mm}
.wp .window h3{font:600 .98em/1.4 var(--font-display)}
.wp .window .line{background:#fff;padding-left:1mm;padding-right:1mm}
.wp .chk{display:flex;flex-direction:column;flex:1}
.wp .chk-head,.wp .chk-row{display:grid;grid-template-columns:5.2mm 1fr 9mm 9mm 10.6mm;gap:1.4mm;align-items:center}
.wp .chk-head{padding-bottom:.8mm;border-bottom:.35mm solid var(--navy);font:600 .78em/1.3 var(--font-mono);color:var(--muted)}
.wp .chk-head span{text-align:center}
.wp .chk-item{flex:1;display:flex;flex-direction:column;justify-content:center;border-bottom:.25mm dotted var(--rule);padding:.8mm 0}
.wp .chk-row .num{width:5.2mm;height:5.2mm;border-radius:50%;background:var(--brand-soft);color:var(--brand);display:flex;align-items:center;justify-content:center;font:700 .85em/1 var(--font-mono)}
.wp .chk-row p{font-size:.96em;line-height:1.3}
.wp .chk-row .cb{justify-self:center}
.wp .extra{display:grid;grid-template-columns:1fr 1fr;gap:2.4mm;margin-top:1mm}
.wp .extra .ruled{min-height:9mm}
.wp .tagt{display:flex;align-items:flex-end;gap:3mm;padding:1.6mm 2.2mm;border:.3mm dashed var(--rule);border-radius:1.6mm;background:var(--soft);margin-top:1.4mm}
.wp .tagt b{font:600 .85em/1.3 var(--font-display);white-space:nowrap}
.wp .tagt .t{flex:1;display:flex;align-items:flex-end;gap:1.4mm;font:600 .8em var(--font-mono);color:var(--muted)}
.wp .tagt .t i{flex:1;min-height:5mm;border-bottom:.3mm solid var(--ink);font-style:normal;color:var(--ink);text-align:center}
.wp .sigs{display:grid;grid-template-columns:1fr 1fr;gap:3mm}
.wp .sig{position:relative;min-height:16mm;border:.3mm solid var(--rule);border-radius:1.6mm;background:#FFFEFA;display:flex;flex-direction:column;justify-content:flex-end}
.wp .sig-img{display:block;max-height:12mm;max-width:90%;margin:1mm auto 0;object-fit:contain}
.wp .sig .cap{margin:0 2mm;padding:.5mm 0 .7mm;border-top:.3mm solid var(--ink);font-size:.78em;line-height:1.35;color:var(--muted);font-weight:600;display:flex;gap:1.4mm}
.wp .sig .cap b{color:var(--ink);font-weight:600}
.wp .decl{background:var(--hazard-soft);border:.3mm dashed var(--hazard-edge);border-radius:2mm;padding:2mm 2.4mm;display:flex;flex-direction:column;gap:2mm}
.wp .decl-tag{align-self:flex-start;font:600 .74em/1.5 var(--font-mono);letter-spacing:.12em;text-transform:uppercase;background:var(--hazard);color:var(--on-hazard);padding:.2mm 2.4mm;border-radius:99px}
.wp .decl p{font-size:.92em;line-height:1.38}
.wp .stmt{display:flex;gap:2mm;align-items:center;padding:1.4mm 2.2mm;border-radius:1.8mm;background:var(--brand-soft);font-weight:500;font-size:.94em;line-height:1.35}
.wp .stmt::before{content:"\2713";flex:none;width:4.6mm;height:4.6mm;border-radius:50%;display:flex;align-items:center;justify-content:center;background:var(--brand);color:#fff;font-size:.9em;font-weight:700;line-height:1}
.wp .hse{display:grid;grid-template-columns:1.5fr 1fr;gap:3mm;flex:1}
.wp .hse .ruled{min-height:14mm}
.wp .c1{display:grid;grid-template-columns:1.05fr 1.5fr 26mm 22mm;gap:3mm;align-items:end}
.wp .status{display:flex;flex-direction:column;gap:1.6mm}
.wp .opt{display:flex;align-items:center;gap:2mm;padding:1.4mm 2.4mm;border:.3mm solid var(--rule);border-radius:1.8mm;background:var(--soft);font:600 1em/1.35 var(--font-display)}
.wp .c2{display:grid;grid-template-columns:1.25fr 1.45fr 26mm 22mm;gap:3mm;align-items:end}
.wp .c2 .decl{align-self:stretch}
.wp .copies{display:flex;flex-wrap:wrap;align-items:center;gap:2mm 5mm;padding:1.4mm 2.4mm;border:.3mm solid var(--rule);border-radius:1.8mm}
.wp .copies .lbl{color:var(--ink);font-size:.9em}
.wp .dt{display:flex;flex-direction:column}
.wp .dt .line{min-height:9mm;padding-top:3mm}
.wp .foot{display:flex;justify-content:space-between;gap:4mm;align-items:center;border-top:.35mm solid var(--navy);padding-top:1mm;font:500 .74em/1.4 var(--font-mono);color:var(--muted)}
.wp .foot b{color:var(--navy);font-weight:600}
.wp[lang="ur"] *{letter-spacing:0!important;text-transform:none!important}
.wp[lang="ur"] .page{--fs:7.9pt;line-height:1.55;gap:2.4mm}
.wp[lang="ur"] .sec-b{gap:1.6mm}
.wp[lang="ur"] .sig{min-height:13mm}
.wp[lang="ur"] .org{line-height:1.7}
.wp[lang="ur"] .sec-h h2,.wp[lang="ur"] .window h3{line-height:1.7}
.wp[lang="ur"] .chk-row p,.wp[lang="ur"] .decl p,.wp[lang="ur"] .stmt{line-height:1.6}
.wp[lang="ur"] .f>label,.wp[lang="ur"] .lbl,.wp[lang="ur"] .sig .cap{line-height:1.6}
.wp[lang="ur"] .chk-row .num,.wp[lang="ur"] .sec-h .n,.wp[lang="ur"] .ticket .no .big{font-family:"IBM Plex Mono",monospace}
.wp[lang="ur"] .line,.wp[lang="ur"] .ruled{line-height:1.8}
@media print{.print-format{width:210mm!important}.wp .page{min-height:296mm;break-inside:avoid}}
</style>

<div class="wp" lang="{{ L }}" dir="{{ 'rtl' if L == 'ur' else 'ltr' }}">
<main class="page">

  <header class="head">
    <div class="brand">
      <div class="mark"><img src="/files/atslogo.png" alt="ATS"></div>
      <div>
        <p class="kicker">{{ t.kicker2 }}</p>
        <h1 class="org">{{ t.org }}</h1>
        <span class="title">{{ t.kicker1 }}</span>
      </div>
    </div>
    <div class="ticket">
      <div class="no">
        <label>{{ t.permit_no }}</label>
        <div class="big">{{ v(doc.permit_no) }}</div>
        {% if doc.permit_color %}<span class="colour"><i style="background:{{ COLORS.get(doc.permit_color, '#999') }}"></i>{{ t.colour }}: {{ t.get(doc.permit_color, doc.permit_color) }}</span>{% endif %}
      </div>
      <div class="meta">
        <div class="f"><label>{{ t.ref }}</label><div class="line">{{ v(doc.reference_no) }}</div></div>
        <div class="f"><label>{{ t.dept }}</label><div class="line">{{ v(doc.department) }}</div></div>
      </div>
    </div>
  </header>

  <div class="cols">
    <div class="col">
      <section class="sec">
        <div class="sec-h"><span class="n">1</span><h2>{{ t.s1 }}</h2></div>
        <div class="sec-b">
          <div class="window">
            <h3>{{ t.valid }}</h3>
            <div class="row3">
              <div class="f"><label>{{ t["from"] }}</label><div class="line">{{ tm(doc.valid_from) }}</div></div>
              <div class="f"><label>{{ t.until }}</label><div class="line">{{ "" if doc.valid_until_work_complete else tm(doc.valid_until) }}</div></div>
              <div class="f"><label>{{ t.day }}</label><div class="line">{{ t.get(doc.valid_day, doc.valid_day or "") }}</div></div>
            </div>
            <span class="cbl">{{ cb(doc.valid_until_work_complete) }}<span>{{ t.until_done }}</span></span>
          </div>
          <div class="row2">
            <div class="f"><label>{{ t.issuedto }}</label><div class="line">{{ v(doc.permit_issued_to_name) }} {% if doc.permit_issued_to %}<small>({{ v(doc.permit_issued_to) }})</small>{% endif %}</div></div>
            <div class="f"><label>{{ t.recvdept }}</label><div class="line">{{ v(doc.receiver_department) }}</div></div>
          </div>
          <div class="f" style="flex:1"><label>{{ t.hazards }}</label><div class="ruled">{{ txt(doc.possible_hazards) }}</div></div>
        </div>
      </section>

      <section class="sec" style="flex:1">
        <div class="sec-h"><span class="n">2</span><h2>{{ t.s2 }}</h2><span class="aside">{{ t.s2_aside }}</span></div>
        <div class="sec-b" style="gap:1mm">
          <div class="chk">
            <div class="chk-head"><span>#</span><span></span><span>{{ t.yes }}</span><span>{{ t.no }}</span><span>{{ t.na }}</span></div>
            {% for c in t.checks %}
            {% set val = doc.get("check_" ~ loop.index) %}
            <div class="chk-item">
              <div class="chk-row"><span class="num">{{ loop.index }}</span><p>{{ c }}</p>{{ cb(val == "Yes") }}{{ cb(val == "No") }}{{ cb(val == "N/A") }}</div>
              {% if loop.index == 6 %}
              <div class="extra">
                <div class="f"><label>{{ t.d_details }}</label><div class="ruled">{{ txt(doc.check_6_details) }}</div></div>
                <div class="f"><label>{{ t.d_safety }}</label><div class="ruled">{{ txt(doc.check_6_safety) }}</div></div>
              </div>
              {% endif %}
            </div>
            {% endfor %}
          </div>
          <div class="tagt">
            <b>{{ t.tag_times }}</b>
            <span class="t">IT<i>{{ tm(doc.tag_it) }}</i></span><span class="t">FT<i>{{ tm(doc.tag_ft) }}</i></span><span class="t">LT<i>{{ tm(doc.tag_lt) }}</i></span>
          </div>
        </div>
      </section>
    </div>

    <div class="col">
      <section class="sec" style="flex:1">
        <div class="sec-h"><span class="n">3</span><h2>{{ t.s3 }}</h2></div>
        <div class="sec-b">
          <div class="f"><label>{{ t.sup }}</label><div class="line">{{ v(doc.site_supervisor_name or doc.site_supervisor) }}{% if doc.site_supervisor_designation %} <small>· {{ v(doc.site_supervisor_designation) }}</small>{% endif %}</div></div>
          <div class="f"><label>{{ t.extra }}</label><div class="ruled" style="min-height:12mm;flex:none">{{ txt(doc.additional_safety) }}</div></div>
          <div class="sigs">
            {{ sig("sign_production_incharge", "r_prod") }}
            {{ sig("sign_permit_issuer", "r_issuer") }}
          </div>
          <div class="decl">
            <span class="decl-tag">{{ t.decl_tag }}</span>
            <p>{{ t.decl_text }}</p>
            <div class="sigs">
              {{ sig("sign_maintenance_incharge", "r_maint") }}
              {{ sig("sign_permit_receiver", "r_recv") }}
            </div>
          </div>
          <div class="hse">
            <div class="f"><label>{{ t.hse_rem }}</label><div class="ruled">{{ txt(doc.hse_remarks) }}</div></div>
            <div style="display:flex;flex-direction:column;gap:2mm">
              <p class="stmt">{{ t.stmt }}</p>
              {{ sig("sign_hse_incharge", "r_hse", ' style="flex:1"') }}
            </div>
          </div>
        </div>
      </section>
    </div>
  </div>

  <section class="sec wp-close">
    <div class="sec-h"><span class="n">4</span><h2>{{ t.s4 }}</h2><span class="aside">{{ t.s4_aside }}</span></div>
    <div class="sec-b" style="gap:2.4mm;flex:none">
      <div class="c1">
        <div class="status">
          <span class="opt">{{ cb(doc.work_status == "Work complete") }}<span>{{ t.w_complete }}</span></span>
          <span class="opt">{{ cb(doc.work_status == "Work incomplete") }}<span>{{ t.w_incomplete }}</span></span>
        </div>
        {{ sig("sign_receiver_closeout", "r_recv") }}
        <div class="dt"><label class="lbl">{{ t.date }}</label><div class="line">{{ dt(doc.receiver_date) }}</div></div>
        <div class="dt"><label class="lbl">{{ t.time }}</label><div class="line">{{ tm(doc.receiver_time) }}</div></div>
      </div>
      <div class="c2">
        <div class="decl">
          <span class="decl-tag">{{ t.decl2_tag }}</span>
          <p>{{ t.decl2_text }}</p>
        </div>
        {{ sig("sign_issuer_closeout", "r_issuer", ' style="min-height:21mm"') }}
        <div class="dt"><label class="lbl">{{ t.date }}</label><div class="line">{{ dt(doc.issuer_date) }}</div></div>
        <div class="dt"><label class="lbl">{{ t.time }}</label><div class="line">{{ tm(doc.issuer_time) }}</div></div>
      </div>
      <div class="copies">
        <span class="lbl">{{ t.copies }}</span>
        <span class="cbl">{{ cb(doc.copy_issuer) }}<span>{{ t.cp_issuer }}</span></span>
        <span class="cbl">{{ cb(doc.copy_receiver) }}<span>{{ t.cp_recv }}</span></span>
        <span class="cbl">{{ cb(doc.copy_hse) }}<span>{{ t.cp_hse }}</span></span>
        <span class="cbl">{{ cb(doc.copy_record) }}<span>{{ t.cp_rec }}</span></span>
      </div>
    </div>
  </section>

  <footer class="foot">
    <span><b>{{ t.org }}</b> · {{ t.kicker1 }} · {{ doc.name }}</span>
    <span>{{ t.foot_r }}</span>
  </footer>
</main>
</div>
